'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { createClient } from '@/utils/supabase/client'

// --- Constants (Fallback if file missing) ---
const CADET_RANKS = [
  'Cadet Private', 'Cadet Private First Class', 'Cadet Corporal', 'Cadet Sergeant', 
  'Cadet Staff Sergeant', 'Cadet Sergeant First Class', 'Cadet Master Sergeant', 
  'Cadet First Sergeant', 'Cadet Sergeant Major', 'Cadet Command Sergeant Major',
  'Cadet Second Lieutenant', 'Cadet First Lieutenant', 'Cadet Captain', 
  'Cadet Major', 'Cadet Lieutenant Colonel'
]

// --- Types ---
type Profile = {
  id: string
  first_name: string
  last_name: string
  email: string
  phone_number: string | null
  room_number: string | null
  grade_level: string | null
  cadet_rank: string | null
  company_id: string | null
  company?: { company_name: string }
  role?: { role_name: string }
  term_demerits: number
  year_demerits: number
  current_tour_balance: number
  has_star_tours?: boolean
  conduct_status: string
  is_on_probation: boolean
  // Sports
  sport_fall?: string
  sport_winter?: string
  sport_spring?: string
  // Parent Info (Mock for now, or real cols if added)
  parent_name?: string
  parent_email?: string
  parent_phone?: string
}

type LedgerEntry = {
  id: string
  created_at: string
  offense_description: string
  demerits: number
  tours: number
  event_type: string
  report_id: string | null
}

export default function ProfileClient({ 
  profile, 
  ledger, 
  canEdit,
  viewerRoleLevel 
}: { 
  profile: Profile
  ledger: LedgerEntry[]
  canEdit: boolean
  viewerRoleLevel: number
}) {
  const supabase = createClient()
  const router = useRouter()
  
  const [isEditing, setIsEditing] = useState(false)
  const [saving, setSaving] = useState(false)
  const [formData, setFormData] = useState({
    room_number: profile.room_number || '',
    grade_level: profile.grade_level || '',
    cadet_rank: profile.cadet_rank || '',
    // Parent info placeholders
    parent_name: profile.parent_name || '',
    parent_phone: profile.parent_phone || ''
  })

  const formatDate = (dateString: string) => new Date(dateString).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })

  const getStatusColor = (status: string) => {
      if (status === 'Unsatisfactory') return 'bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800'
      if (status === 'Deficient') return 'bg-orange-50 text-orange-700 border-orange-200 dark:bg-orange-900/20 dark:text-orange-300 dark:border-orange-800'
      return 'bg-green-50 text-green-700 border-green-200 dark:bg-green-900/20 dark:text-green-300 dark:border-green-800'
  }

  const handleSave = async () => {
      setSaving(true)
      const { error } = await supabase
          .from('profiles')
          .update({
              room_number: formData.room_number,
              grade_level: formData.grade_level,
              cadet_rank: formData.cadet_rank,
          })
          .eq('id', profile.id)
      
      setSaving(false)
      if (error) alert(`Error: ${error.message}`)
      else { setIsEditing(false); router.refresh(); }
  }

  const isFaculty = viewerRoleLevel >= 50;

  // Sport Icon Helper
  const getSportIcon = (sportName: string = '') => {
      const lower = sportName.toLowerCase();
      if (lower.includes('basketball')) return <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> // Generic Ball
      if (lower.includes('football')) return <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg> // Generic Play
      if (lower.includes('cross country') || lower.includes('track')) return <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg> // Bolt/Run
      if (lower.includes('baseball')) return <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" /></svg> // Plate?
      return <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg> // Jersey
  }

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-12">
      
      {/* --- TOP: IDENTITY HEADER --- */}
      <div className="bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden">
        {/* Restored Gradient */}
        <div className="h-32 bg-gradient-to-r from-indigo-500 to-purple-600 dark:from-indigo-900 dark:to-purple-900"></div>
        
        <div className="px-6 pb-6 relative flex flex-col md:flex-row items-end md:items-center gap-6 -mt-12 md:-mt-16">
            
            {/* Photo Placeholder */}
            <div className="relative">
                <div className="w-32 h-32 rounded-full border-4 border-white dark:border-gray-800 bg-gray-200 dark:bg-gray-700 flex items-center justify-center text-4xl font-bold text-gray-400 dark:text-gray-500 shadow-md">
                    {profile.first_name[0]}{profile.last_name[0]}
                </div>
            </div>

            <div className="flex-1 pb-2 text-center md:text-left">
                <h1 className="text-3xl font-bold text-gray-900 dark:text-white">{profile.cadet_rank || 'Cadet'} {profile.last_name}, {profile.first_name}</h1>
                <div className="flex flex-wrap justify-center md:justify-start gap-4 mt-2 text-sm font-medium text-gray-600 dark:text-gray-400">
                    <span className="flex items-center gap-1">
                        {/* Company Icon */}
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
                        {profile.company?.company_name || 'Unassigned'}
                    </span>
                    <span className="hidden md:inline text-gray-300 dark:text-gray-600">•</span>
                    <span className="flex items-center gap-1">
                        {/* Role Icon */}
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        {profile.role?.role_name || 'No Role'}
                    </span>
                    <span className="hidden md:inline text-gray-300 dark:text-gray-600">•</span>
                    <span className="flex items-center gap-1">
                        {/* Email Icon */}
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
                        {profile.email}
                    </span>
                </div>
            </div>

            <div className="flex gap-3 pb-2 w-full md:w-auto justify-center md:justify-end">
                {canEdit && (
                    <button 
                        onClick={() => setIsEditing(!isEditing)}
                        className={`px-4 py-2 rounded-md shadow-sm text-sm font-medium transition-colors ${isEditing ? 'bg-gray-200 text-gray-800 dark:bg-gray-700 dark:text-gray-200' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}
                    >
                        {isEditing ? 'Cancel Edit' : 'Edit Profile'}
                    </button>
                )}
            </div>
        </div>
      </div>

      {/* --- GRID: DATA BOXES --- */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        
        {/* 1. STATUS BOX */}
        <div className="bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 rounded-xl p-5 flex flex-col gap-4">
            <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider">Status</h3>
            
            {/* Conduct */}
            <div className={`p-3 rounded-lg border ${getStatusColor(profile.conduct_status)}`}>
                <div className="flex justify-between items-center">
                    <span className="text-xs font-bold uppercase opacity-75">Conduct</span>
                    <span className="font-bold">{profile.conduct_status}</span>
                </div>
            </div>

            {/* Probation */}
            <div className={`p-3 rounded-lg border ${profile.is_on_probation ? 'bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-300 dark:border-red-800' : 'bg-gray-50 text-gray-700 border-gray-200 dark:bg-gray-700/50 dark:text-gray-300 dark:border-gray-600'}`}>
                <div className="flex justify-between items-center">
                    <span className="text-xs font-bold uppercase opacity-75">Probation</span>
                    <span className="font-bold">{profile.is_on_probation ? 'On Probation' : 'Not on Probation'}</span>
                </div>
            </div>

            {/* Tours */}
            <div className="flex justify-between items-center p-3 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
                <span className="text-xs font-bold text-gray-500 uppercase">Tours Owed</span>
                <span className={`text-xl font-bold ${profile.current_tour_balance > 0 ? 'text-red-600 dark:text-red-400' : 'text-gray-900 dark:text-white'}`}>
                    {profile.has_star_tours ? '*' : profile.current_tour_balance}
                </span>
            </div>
        </div>

        {/* 2. SPORTS (Big Cards with Icons) */}
        <div className="bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 rounded-xl p-5">
            <div className="flex justify-between items-center mb-4">
                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider">Athletics</h3>
                <span className="text-xs text-indigo-600 dark:text-indigo-400 cursor-pointer hover:underline">View All</span>
            </div>
            <div className="space-y-3">
                
                {/* Fall */}
                <Link href="#" className="flex items-center gap-4 p-3 bg-gray-50 hover:bg-gray-100 dark:bg-gray-700/30 dark:hover:bg-gray-700/50 rounded-xl transition-colors border border-transparent hover:border-gray-200 dark:hover:border-gray-600 group">
                    <div className="p-3 bg-white dark:bg-gray-800 rounded-full text-gray-400 group-hover:text-indigo-500 transition-colors shadow-sm">
                        {getSportIcon(profile.sport_fall || 'fall')}
                    </div>
                    <div className="flex-1">
                        <span className="block text-xs font-bold text-gray-400 uppercase tracking-wide mb-0.5">Fall</span>
                        <span className="block text-sm font-bold text-gray-900 dark:text-white">{profile.sport_fall || 'No Sport'}</span>
                    </div>
                </Link>

                {/* Winter */}
                <Link href="#" className="flex items-center gap-4 p-3 bg-gray-50 hover:bg-gray-100 dark:bg-gray-700/30 dark:hover:bg-gray-700/50 rounded-xl transition-colors border border-transparent hover:border-gray-200 dark:hover:border-gray-600 group">
                    <div className="p-3 bg-white dark:bg-gray-800 rounded-full text-gray-400 group-hover:text-indigo-500 transition-colors shadow-sm">
                        {getSportIcon(profile.sport_winter || 'winter')}
                    </div>
                    <div className="flex-1">
                        <span className="block text-xs font-bold text-gray-400 uppercase tracking-wide mb-0.5">Winter</span>
                        <span className="block text-sm font-bold text-gray-900 dark:text-white">{profile.sport_winter || 'No Sport'}</span>
                    </div>
                </Link>

                {/* Spring */}
                <Link href="#" className="flex items-center gap-4 p-3 bg-gray-50 hover:bg-gray-100 dark:bg-gray-700/30 dark:hover:bg-gray-700/50 rounded-xl transition-colors border border-transparent hover:border-gray-200 dark:hover:border-gray-600 group">
                    <div className="p-3 bg-white dark:bg-gray-800 rounded-full text-gray-400 group-hover:text-indigo-500 transition-colors shadow-sm">
                        {getSportIcon(profile.sport_spring || 'spring')}
                    </div>
                    <div className="flex-1">
                        <span className="block text-xs font-bold text-gray-400 uppercase tracking-wide mb-0.5">Spring</span>
                        <span className="block text-sm font-bold text-gray-900 dark:text-white">{profile.sport_spring || 'No Sport'}</span>
                    </div>
                </Link>

            </div>
        </div>

        {/* 3. CONTACT / DETAILS */}
        <div className="bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 rounded-xl p-5">
            <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-4">Details</h3>
            
            {isEditing ? (
                <div className="space-y-3">
                    <div>
                        <label className="text-xs font-medium text-gray-500">Rank</label>
                        <select 
                            value={formData.cadet_rank} 
                            onChange={e => setFormData({...formData, cadet_rank: e.target.value})} 
                            className="w-full border rounded p-1 text-sm dark:bg-gray-900 dark:text-white"
                        >
                            <option value="">Select Rank</option>
                            {CADET_RANKS.map(r => <option key={r} value={r}>{r}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="text-xs font-medium text-gray-500">Room</label>
                        <input type="text" value={formData.room_number} onChange={e => setFormData({...formData, room_number: e.target.value})} className="w-full border rounded p-1 text-sm dark:bg-gray-900 dark:text-white" />
                    </div>
                    <div>
                        <label className="text-xs font-medium text-gray-500">Grade</label>
                        <input type="text" value={formData.grade_level} onChange={e => setFormData({...formData, grade_level: e.target.value})} className="w-full border rounded p-1 text-sm dark:bg-gray-900 dark:text-white" />
                    </div>
                    <button onClick={handleSave} disabled={saving} className="w-full mt-2 py-1.5 bg-green-600 text-white rounded text-sm font-medium hover:bg-green-700">{saving ? 'Saving...' : 'Save Changes'}</button>
                </div>
            ) : (
                <div className="space-y-4">
                    <div className="flex justify-between border-b dark:border-gray-700 pb-2">
                        <span className="text-sm text-gray-500">Company</span>
                        <span className="text-sm font-medium text-gray-900 dark:text-white">{profile.company?.company_name || '-'}</span>
                    </div>
                    <div className="flex justify-between border-b dark:border-gray-700 pb-2">
                        <span className="text-sm text-gray-500">Room</span>
                        <span className="text-sm font-medium text-gray-900 dark:text-white">{profile.room_number || '-'}</span>
                    </div>
                    <div className="flex justify-between border-b dark:border-gray-700 pb-2">
                        <span className="text-sm text-gray-500">Grade</span>
                        <span className="text-sm font-medium text-gray-900 dark:text-white">{profile.grade_level || '-'}</span>
                    </div>
                    <div className="flex justify-between pb-2">
                        <span className="text-sm text-gray-500">Rank</span>
                        <span className="text-sm font-medium text-gray-900 dark:text-white">{profile.cadet_rank || '-'}</span>
                    </div>
                </div>
            )}
        </div>

      </div>

      {/* --- BOTTOM ROW: SPLIT VIEW --- */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          
          {/* LEFT: DISCIPLINARY RECORD */}
          <div className="bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden h-96 flex flex-col">
            <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-700/30">
              <h3 className="text-sm font-bold text-gray-900 dark:text-white uppercase tracking-wider">Disciplinary Record</h3>
            </div>
            <div className="overflow-y-auto flex-1">
                {ledger.length > 0 ? (
                <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
                    <thead className="bg-gray-50 dark:bg-gray-700/50 sticky top-0">
                        <tr>
                        <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">Date</th>
                        <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">Event</th>
                        <th className="px-4 py-2 text-center text-xs font-medium text-gray-500 dark:text-gray-300 uppercase">Dem</th>
                        <th className="px-4 py-2"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                        {ledger.map((entry) => (
                        <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors text-sm">
                            <td className="px-4 py-2 text-gray-600 dark:text-gray-300 whitespace-nowrap">{formatDate(entry.created_at)}</td>
                            <td className="px-4 py-2 text-gray-900 dark:text-white truncate max-w-[150px]">{entry.offense_description}</td>
                            <td className="px-4 py-2 text-center font-mono text-gray-900 dark:text-white">{entry.demerits > 0 ? entry.demerits : '-'}</td>
                            <td className="px-4 py-2 text-right">
                                {entry.report_id && <Link href={`/report/${entry.report_id}`} className="text-indigo-600 hover:underline text-xs">View</Link>}
                            </td>
                        </tr>
                        ))}
                    </tbody>
                </table>
                ) : (
                <div className="p-8 text-center text-gray-500 dark:text-gray-400 italic text-sm">No disciplinary history recorded.</div>
                )}
            </div>
          </div>

          {/* RIGHT: PARENT CONTACT (FACULTY ONLY) */}
          {isFaculty ? (
              <div className="bg-white dark:bg-gray-800 shadow-sm border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden h-96 flex flex-col">
                <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700 bg-amber-50 dark:bg-amber-900/20 flex justify-between items-center">
                    <h3 className="text-sm font-bold text-amber-900 dark:text-amber-100 uppercase tracking-wider flex items-center gap-2">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
                        Parent / Guardian
                    </h3>
                    <span className="text-[10px] font-bold bg-amber-200 text-amber-800 px-2 py-0.5 rounded uppercase">Faculty Only</span>
                </div>
                <div className="p-6 flex-1 overflow-y-auto">
                    <div className="space-y-6">
                        <div>
                            <p className="text-xs text-gray-500 uppercase font-bold mb-1">Primary Contact</p>
                            <p className="text-lg font-bold text-gray-900 dark:text-white">{profile.parent_name || 'Not Listed'}</p>
                            <div className="mt-2 flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
                                <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" /></svg>
                                {profile.parent_phone || '(---) --- ----'}
                            </div>
                            <div className="mt-1 flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
                                <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
                                {profile.parent_email || 'No Email'}
                            </div>
                        </div>
                    </div>
                </div>
              </div>
          ) : (
              <div className="bg-gray-50 dark:bg-gray-800/50 border border-dashed border-gray-300 dark:border-gray-700 rounded-xl h-96 flex items-center justify-center text-gray-400 dark:text-gray-600 text-sm">
                  Restricted Access
              </div>
          )}

      </div>

    </div>
  )
}